[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#2-aggregates-and-commands]

#### 2. Aggregates and Commands

Aggregates are domain entities that enforce business rules and produce events. They are the consistency boundary for event sourcing.

**Command Processing Pattern:**

```csharp
// Command - represents intent to change state
public record AdjudicateClaimCommand(
    Guid ClaimId,
    Guid AdjudicatorId,
    string AdjudicationNotes
);

// Claim Aggregate - enforces business rules, produces events
public class Claim
{
    // Aggregate state (derived from events)
    public Guid Id { get; private set; }
    public string ClaimNumber { get; private set; }
    public ClaimStatus Status { get; private set; }
    public decimal BilledAmount { get; private set; }
    public decimal ApprovedAmount { get; private set; }
    public Guid MemberId { get; private set; }
    public Guid ProviderId { get; private set; }

    // Events that need to be persisted
    private readonly List<IDomainEvent> _uncommittedEvents = new();
    public IReadOnlyList<IDomainEvent> UncommittedEvents => _uncommittedEvents;

    // Version tracking for optimistic concurrency
    public long Version { get; private set; }

    // Command handler - validates rules and produces events
    public void Adjudicate(
        AdjudicateClaimCommand command,
        MemberEligibility eligibility,
        ProviderCredentials credentials,
        decimal contractRate)
    {
        // Business rule validation
        if (Status != ClaimStatus.Validated)
            throw new InvalidOperationException(
                $"Cannot adjudicate claim in status {Status}");

        if (!eligibility.IsEligibleForService(ServiceDate))
            throw new BusinessRuleException(
                "Member not eligible for service on date of service");

        if (!credentials.IsActiveOnDate(ServiceDate))
            throw new BusinessRuleException(
                "Provider not credentialed on date of service");

        // Calculate approved amount based on contract rate
        var approvedAmount = CalculateApprovedAmount(BilledAmount, contractRate);

        // Produce event (not persisted yet)
        var adjudicatedEvent = new ClaimAdjudicatedEvent
        {
            ClaimId = Id,
            ClaimNumber = ClaimNumber,
            AdjudicatedBy = command.AdjudicatorId,
            AdjudicatedAt = DateTime.UtcNow,
            AdjudicationResult = approvedAmount > 0
                ? AdjudicationResult.Approved
                : AdjudicationResult.Denied,
            BilledAmount = BilledAmount,
            ApprovedAmount = approvedAmount,
            AdjustmentReason = $"Contract rate {contractRate:P} applied",
            RulesEvaluated = new[]
            {
                "MemberEligibilityCheck",
                "ProviderCredentialCheck",
                "ContractPricingApplied"
            },
            Notes = command.AdjudicationNotes
        };

        // Apply event to update aggregate state
        Apply(adjudicatedEvent);

        // Add to uncommitted events for persistence
        _uncommittedEvents.Add(adjudicatedEvent);
    }

    // Event application - updates aggregate state
    private void Apply(ClaimAdjudicatedEvent @event)
    {
        Status = @event.AdjudicationResult == AdjudicationResult.Approved
            ? ClaimStatus.Approved
            : ClaimStatus.Denied;
        ApprovedAmount = @event.ApprovedAmount;
    }

    // Reconstitute aggregate from event history
    public static Claim LoadFromHistory(IEnumerable<IDomainEvent> history)
    {
        var claim = new Claim();

        foreach (var @event in history)
        {
            // Apply each historical event to rebuild state
            claim.ApplyEvent(@event);
            claim.Version++;
        }

        return claim;
    }

    private void ApplyEvent(IDomainEvent @event)
    {
        switch (@event)
        {
            case ClaimSubmittedEvent e:
                Apply(e);
                break;
            case ClaimValidatedEvent e:
                Apply(e);
                break;
            case ClaimAdjudicatedEvent e:
                Apply(e);
                break;
            // ... other event types
        }
    }

    private void Apply(ClaimSubmittedEvent @event)
    {
        Id = @event.ClaimId;
        ClaimNumber = @event.ClaimNumber;
        MemberId = @event.MemberId;
        ProviderId = @event.ProviderId;
        BilledAmount = @event.BilledAmount;
        Status = ClaimStatus.Submitted;
    }

    private void Apply(ClaimValidatedEvent @event)
    {
        Status = ClaimStatus.Validated;
    }

    private decimal CalculateApprovedAmount(decimal billedAmount, decimal contractRate)
    {
        return billedAmount * contractRate;
    }
}
```

**Event Application Command Service:**

```csharp
public class ClaimCommandService
{
    private readonly IEventStore _eventStore;
    private readonly IEligibilityService _eligibilityService;
    private readonly IProviderService _providerService;

    public async Task<AdjudicationResult> AdjudicateClaimAsync(
        AdjudicateClaimCommand command)
    {
        // 1. Load aggregate from event history
        var events = await _eventStore.LoadEventsAsync(command.ClaimId);
        var claim = Claim.LoadFromHistory(events);

        // 2. Load required data for business rule validation
        var eligibility = await _eligibilityService
            .GetEligibilityAsync(claim.MemberId, claim.ServiceDate);
        var credentials = await _providerService
            .GetCredentialsAsync(claim.ProviderId, claim.ServiceDate);
        var contractRate = await _providerService
            .GetContractRateAsync(claim.ProviderId, claim.ServiceCode);

        // 3. Execute command (produces events)
        claim.Adjudicate(command, eligibility, credentials, contractRate);

        // 4. Persist events to event store
        await _eventStore.AppendEventsAsync(
            claim.Id,
            claim.UncommittedEvents,
            expectedVersion: claim.Version  // Optimistic concurrency
        );

        // 5. Return result
        return new AdjudicationResult
        {
            ClaimId = claim.Id,
            Status = claim.Status,
            ApprovedAmount = claim.ApprovedAmount
        };
    }
}
```

