[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#3-event-handlers-and-projections]

#### 3. Event Handlers and Projections

Event handlers subscribe to events and update read models (projections) optimized for queries. This implements the CQRS pattern.

**Event Handler Pattern:**

```csharp
// Event handler updates read model
public class ClaimQueryModelUpdater : IEventHandler
{
    private readonly ClaimsQueryDbContext _queryDb;

    public async Task HandleAsync(ClaimAdjudicatedEvent @event)
    {
        // Update denormalized query model
        var claimQueryModel = await _queryDb.Claims
            .FirstOrDefaultAsync(c => c.ClaimId == @event.ClaimId);

        if (claimQueryModel == null)
        {
            // Handle missing query model (rebuild from events)
            throw new InvalidOperationException(
                $"Claim query model not found for {event.ClaimId}");
        }

        // Update query model fields
        claimQueryModel.Status = @event.AdjudicationResult.ToString();
        claimQueryModel.ApprovedAmount = @event.ApprovedAmount;
        claimQueryModel.AdjudicatedBy = @event.AdjudicatedBy;
        claimQueryModel.AdjudicatedAt = @event.AdjudicatedAt;
        claimQueryModel.LastModifiedAt = DateTime.UtcNow;

        // Save to query database
        await _queryDb.SaveChangesAsync();

        // Event handler is idempotent (safe to replay)
    }

    public async Task HandleAsync(ClaimSubmittedEvent @event)
    {
        // Create new query model record
        var claimQueryModel = new ClaimQueryModel
        {
            ClaimId = @event.ClaimId,
            ClaimNumber = @event.ClaimNumber,
            MemberId = @event.MemberId,
            MemberName = @event.MemberName,  // Denormalized for query performance
            ProviderId = @event.ProviderId,
            ProviderName = @event.ProviderName,  // Denormalized
            BilledAmount = @event.BilledAmount,
            SubmittedAt = @event.SubmittedAt,
            Status = "Submitted",
            LastModifiedAt = DateTime.UtcNow
        };

        _queryDb.Claims.Add(claimQueryModel);
        await _queryDb.SaveChangesAsync();
    }
}

// Query model optimized for reads
public class ClaimQueryModel
{
    public Guid ClaimId { get; set; }
    public string ClaimNumber { get; set; }

    // Denormalized member info for query performance
    public Guid MemberId { get; set; }
    public string MemberName { get; set; }
    public string MemberNumber { get; set; }

    // Denormalized provider info
    public Guid ProviderId { get; set; }
    public string ProviderName { get; set; }
    public string ProviderNPI { get; set; }

    // Claim financial info
    public decimal BilledAmount { get; set; }
    public decimal ApprovedAmount { get; set; }

    // Status and timestamps
    public string Status { get; set; }
    public DateTime SubmittedAt { get; set; }
    public DateTime? AdjudicatedAt { get; set; }
    public Guid? AdjudicatedBy { get; set; }
    public DateTime LastModifiedAt { get; set; }

    // Indexed for common queries
}
```

**Projection Rebuild Capability:**

```csharp
// Rebuild projection from event store
public class ProjectionRebuilder
{
    private readonly IEventStore _eventStore;
    private readonly ClaimsQueryDbContext _queryDb;

    public async Task RebuildClaimProjectionAsync()
    {
        Console.WriteLine("Rebuilding claim projection from event store...");

        // 1. Clear existing projection
        await _queryDb.Database.ExecuteSqlRawAsync("TRUNCATE TABLE Claims");

        // 2. Stream all claim events from event store
        await foreach (var @event in _eventStore.StreamAllEventsAsync("Claim"))
        {
            // 3. Apply event to projection
            await ApplyEventToProjectionAsync(@event);

            if (@event.SequenceNumber % 10000 == 0)
                Console.WriteLine($"Processed {event.SequenceNumber} events...");
        }

        Console.WriteLine("Projection rebuild complete!");
    }

    private async Task ApplyEventToProjectionAsync(IDomainEvent @event)
    {
        var handler = new ClaimQueryModelUpdater(_queryDb);

        switch (@event)
        {
            case ClaimSubmittedEvent e:
                await handler.HandleAsync(e);
                break;
            case ClaimAdjudicatedEvent e:
                await handler.HandleAsync(e);
                break;
            // ... other event types
        }
    }
}
```

