[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#4-snapshots-for-performance]

#### 4. Snapshots for Performance

For aggregates with long event histories, snapshots improve performance by storing periodic state checkpoints.

**Snapshot Pattern:**

```csharp
// Snapshot schema
CREATE TABLE snapshots (
    aggregate_id UUID PRIMARY KEY,
    aggregate_type VARCHAR(100) NOT NULL,
    sequence_number BIGINT NOT NULL,  -- Event sequence at snapshot time
    snapshot_data JSONB NOT NULL,     -- Serialized aggregate state
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

// Snapshot implementation
public class SnapshotStore
{
    private const int SNAPSHOT_FREQUENCY = 100;  // Snapshot every 100 events

    public async Task<Claim?> LoadAggregateWithSnapshotAsync(Guid claimId)
    {
        // 1. Load latest snapshot (if exists)
        var snapshot = await LoadSnapshotAsync(claimId);

        Claim claim;
        long fromSequence;

        if (snapshot != null)
        {
            // Start from snapshot
            claim = snapshot.Claim;
            fromSequence = snapshot.SequenceNumber + 1;
        }
        else
        {
            // No snapshot, start from beginning
            claim = new Claim();
            fromSequence = 0;
        }

        // 2. Load events since snapshot
        var events = await _eventStore.LoadEventsSinceAsync(
            claimId,
            fromSequence);

        // 3. Apply events to aggregate
        foreach (var @event in events)
        {
            claim.ApplyEvent(@event);
            claim.Version++;
        }

        return claim;
    }

    public async Task SaveWithSnapshotAsync(Claim claim)
    {
        // 1. Append events to event store
        await _eventStore.AppendEventsAsync(
            claim.Id,
            claim.UncommittedEvents,
            expectedVersion: claim.Version
        );

        // 2. Check if snapshot needed
        if (claim.Version % SNAPSHOT_FREQUENCY == 0)
        {
            await CreateSnapshotAsync(claim);
        }
    }

    private async Task CreateSnapshotAsync(Claim claim)
    {
        var snapshot = new ClaimSnapshot
        {
            AggregateId = claim.Id,
            AggregateType = "Claim",
            SequenceNumber = claim.Version,
            SnapshotData = JsonSerializer.Serialize(claim),
            CreatedAt = DateTime.UtcNow
        };

        await _snapshotDb.UpsertAsync(snapshot);
    }
}
```

**Snapshot Strategy Considerations:**

| Scenario | Snapshot Frequency | Rationale |
|----------|-------------------|-----------|
| **Claims (Low Volume)** | Every 50 events | Claims typically have 5-15 events; snapshot rarely needed |
| **Member Eligibility (High Volume)** | Every 100 events | Members may have 100+ eligibility changes over lifetime |
| **Provider Credentials (Medium Volume)** | Every 20 events | Credential renewals every 3 years with ~20 events per cycle |

