[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#6-temporal-queries]

#### 6. Temporal Queries

Event sourcing enables powerful temporal queries by replaying events to specific points in time.

**Temporal Query Implementation:**

```csharp
public class TemporalQueryService
{
    private readonly IEventStore _eventStore;

    // Query: "What was the claim status on June 15, 2023?"
    public async Task<ClaimState> GetClaimStateAtTimeAsync(
        Guid claimId,
        DateTime pointInTime)
    {
        // Load all events up to the specified time
        var events = await _eventStore.LoadEventsUntilAsync(
            claimId,
            pointInTime);

        // Replay events to reconstruct state at that time
        var claim = Claim.LoadFromHistory(events);

        return new ClaimState
        {
            ClaimId = claim.Id,
            Status = claim.Status,
            ApprovedAmount = claim.ApprovedAmount,
            AsOfDate = pointInTime
        };
    }

    // Query: "How much did we pay Provider XYZ in Q3 2023?"
    public async Task<ProviderPaymentSummary> GetProviderPaymentsInPeriodAsync(
        Guid providerId,
        DateTime startDate,
        DateTime endDate)
    {
        // Stream payment events for provider in date range
        var paymentEvents = await _eventStore
            .QueryEventsAsync<PaymentScheduledEvent>(
                filter: e => e.ProviderId == providerId
                          && e.PaymentDate >= startDate
                          && e.PaymentDate <= endDate
            );

        // Aggregate payment totals
        var totalPaid = paymentEvents.Sum(e => e.PaymentAmount);
        var claimCount = paymentEvents.Select(e => e.ClaimId).Distinct().Count();

        return new ProviderPaymentSummary
        {
            ProviderId = providerId,
            PeriodStart = startDate,
            PeriodEnd = endDate,
            TotalPaid = totalPaid,
            ClaimCount = claimCount
        };
    }

    // Query: "How many members were eligible on December 31, 2023?"
    public async Task<EligibilitySnapshot> GetEligibilitySnapshotAsync(
        DateTime snapshotDate)
    {
        var eligibleMembers = new HashSet<Guid>();

        // Stream all eligibility events up to snapshot date
        await foreach (var @event in _eventStore
            .StreamEventsUntilAsync<MemberEligibilityEvent>(snapshotDate))
        {
            switch (@event)
            {
                case MemberEnrolledEvent e:
                    eligibleMembers.Add(e.MemberId);
                    break;

                case EligibilityTerminatedEvent e:
                    eligibleMembers.Remove(e.MemberId);
                    break;

                case EligibilitySpanAddedEvent e:
                    if (e.EffectiveDate <= snapshotDate
                        && e.TerminationDate >= snapshotDate)
                        eligibleMembers.Add(e.MemberId);
                    break;
            }
        }

        return new EligibilitySnapshot
        {
            SnapshotDate = snapshotDate,
            EligibleMemberCount = eligibleMembers.Count,
            EligibleMembers = eligibleMembers.ToList()
        };
    }
}
```

