[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#7-integration-with-external-systems]

#### 7. Integration with External Systems

Publish domain events as integration events for external system consumption.

**Integration Event Publishing:**

```csharp
public class IntegrationEventPublisher : IEventHandler
{
    private readonly IMessageBus _messageBus;  // Kafka, RabbitMQ, etc.

    public async Task HandleAsync(ClaimAdjudicatedEvent domainEvent)
    {
        // Translate domain event to integration event
        var integrationEvent = new ClaimAdjudicatedIntegrationEvent
        {
            EventId = Guid.NewGuid(),
            EventType = "ClaimAdjudicated",
            EventVersion = "1.0",
            Timestamp = DateTime.UtcNow,

            // Enrich with additional context for consumers
            Payload = new
            {
                ClaimId = domainEvent.ClaimId,
                ClaimNumber = domainEvent.ClaimNumber,
                MemberId = domainEvent.MemberId,
                ProviderId = domainEvent.ProviderId,
                AdjudicationResult = domainEvent.AdjudicationResult,
                ApprovedAmount = domainEvent.ApprovedAmount,

                // Additional context not in domain event
                StateCode = await GetStateCodeAsync(domainEvent.ClaimId),
                PaymentScheduleDate = CalculatePaymentDate(domainEvent)
            }
        };

        // Publish to message bus with idempotency key
        await _messageBus.PublishAsync(
            topic: "claims.adjudicated",
            message: integrationEvent,
            idempotencyKey: domainEvent.ClaimId.ToString()
        );
    }
}
```

