[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#option-a-postgresql-event-store-recommended-for-gainwell]

#### Option A: PostgreSQL Event Store (Recommended for Gainwell)

**Advantages**: Leverages existing database expertise, simple deployment, ACID transactions, flexible ad-hoc querying

**Setup Steps:**

```sql
-- 1. Create events table
CREATE TABLE events (
    event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    aggregate_type VARCHAR(100) NOT NULL,
    aggregate_id UUID NOT NULL,
    event_type VARCHAR(200) NOT NULL,
    event_version INT NOT NULL DEFAULT 1,
    sequence_number BIGINT NOT NULL,
    event_data JSONB NOT NULL,
    metadata JSONB NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT uk_aggregate_sequence
        UNIQUE (aggregate_id, sequence_number)
);

-- 2. Create indexes for common access patterns
CREATE INDEX idx_events_aggregate
    ON events(aggregate_id, sequence_number);

CREATE INDEX idx_events_type_created
    ON events(event_type, created_at);

CREATE INDEX idx_events_created
    ON events(created_at);

-- 3. Create snapshots table
CREATE TABLE snapshots (
    aggregate_id UUID PRIMARY KEY,
    aggregate_type VARCHAR(100) NOT NULL,
    sequence_number BIGINT NOT NULL,
    snapshot_data JSONB NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- 4. Create projection checkpoint table (tracks projection progress)
CREATE TABLE projection_checkpoints (
    projection_name VARCHAR(100) PRIMARY KEY,
    last_processed_event_id UUID NOT NULL,
    last_processed_sequence BIGINT NOT NULL,
    last_processed_at TIMESTAMP NOT NULL DEFAULT NOW()
);
```

**PostgreSQL Event Store Implementation:**

```csharp
public class PostgreSqlEventStore : IEventStore
{
    private readonly NpgsqlConnection _connection;

    public async Task AppendEventsAsync(
        Guid aggregateId,
        IEnumerable<IDomainEvent> events,
        long expectedVersion)
    {
        using var transaction = await _connection.BeginTransactionAsync();

        try
        {
            // Get current version from database
            var currentVersion = await GetAggregateVersionAsync(aggregateId);

            // Optimistic concurrency check
            if (currentVersion != expectedVersion)
            {
                throw new ConcurrencyException(
                    $"Expected version {expectedVersion} but found {currentVersion}");
            }

            // Append each event
            long sequenceNumber = currentVersion;
            foreach (var @event in events)
            {
                sequenceNumber++;

                var sql = @"
                    INSERT INTO events (
                        aggregate_type, aggregate_id, event_type,
                        event_version, sequence_number, event_data, metadata
                    )
                    VALUES (
                        @AggregateType, @AggregateId, @EventType,
                        @EventVersion, @SequenceNumber, @EventData, @Metadata
                    )";

                await _connection.ExecuteAsync(sql, new
                {
                    AggregateType = @event.AggregateType,
                    AggregateId = aggregateId,
                    EventType = @event.GetType().Name,
                    EventVersion = @event.Version,
                    SequenceNumber = sequenceNumber,
                    EventData = JsonSerializer.SerializeToUtf8Bytes(@event),
                    Metadata = JsonSerializer.SerializeToUtf8Bytes(new
                    {
                        UserId = @event.UserId,
                        Timestamp = @event.Timestamp,
                        CorrelationId = @event.CorrelationId
                    })
                }, transaction);
            }

            await transaction.CommitAsync();
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
    }

    public async Task<IEnumerable<IDomainEvent>> LoadEventsAsync(
        Guid aggregateId)
    {
        var sql = @"
            SELECT event_type, event_version, event_data, metadata, sequence_number
            FROM events
            WHERE aggregate_id = @AggregateId
            ORDER BY sequence_number ASC";

        var rows = await _connection.QueryAsync(sql, new { AggregateId = aggregateId });

        var events = new List<IDomainEvent>();
        foreach (var row in rows)
        {
            var @event = DeserializeEvent(
                row.event_type,
                row.event_version,
                row.event_data);
            events.Add(@event);
        }

        return events;
    }

    public async Task<IEnumerable<IDomainEvent>> LoadEventsUntilAsync(
        Guid aggregateId,
        DateTime pointInTime)
    {
        var sql = @"
            SELECT event_type, event_version, event_data, metadata, sequence_number
            FROM events
            WHERE aggregate_id = @AggregateId
              AND created_at <= @PointInTime
            ORDER BY sequence_number ASC";

        var rows = await _connection.QueryAsync(sql, new
        {
            AggregateId = aggregateId,
            PointInTime = pointInTime
        });

        return rows.Select(row => DeserializeEvent(
            row.event_type,
            row.event_version,
            row.event_data));
    }

    private async Task<long> GetAggregateVersionAsync(Guid aggregateId)
    {
        var sql = @"
            SELECT COALESCE(MAX(sequence_number), 0)
            FROM events
            WHERE aggregate_id = @AggregateId";

        return await _connection.ExecuteScalarAsync<long>(
            sql,
            new { AggregateId = aggregateId });
    }

    private IDomainEvent DeserializeEvent(
        string eventType,
        int eventVersion,
        byte[] eventData)
    {
        // Use event type registry to map event name to .NET type
        var type = EventTypeRegistry.GetEventType(eventType, eventVersion);
        return (IDomainEvent)JsonSerializer.Deserialize(eventData, type);
    }
}
```

