**EventStoreDB Implementation:**

```csharp
public class EventStoreDbEventStore : IEventStore
{
    private readonly EventStoreClient _client;

    public EventStoreDbEventStore()
    {
        var settings = EventStoreClientSettings
            .Create("esdb://localhost:2113?tls=false");
        _client = new EventStoreClient(settings);
    }

    public async Task AppendEventsAsync(
        Guid aggregateId,
        IEnumerable<IDomainEvent> events,
        long expectedVersion)
    {
        var streamName = $"Claim-{aggregateId}";

        var eventData = events.Select(@event => new EventData(
            eventId: Uuid.NewUuid(),
            type: @event.GetType().Name,
            data: JsonSerializer.SerializeToUtf8Bytes(@event),
            metadata: JsonSerializer.SerializeToUtf8Bytes(new
            {
                @event.UserId,
                @event.Timestamp,
                @event.CorrelationId
            })
        ));

        try
        {
            await _client.AppendToStreamAsync(
                streamName,
                StreamRevision.FromInt64(expectedVersion),
                eventData
            );
        }
        catch (WrongExpectedVersionException)
        {
            throw new ConcurrencyException(
                $"Concurrency conflict for aggregate {aggregateId}");
        }
    }

    public async Task<IEnumerable<IDomainEvent>> LoadEventsAsync(
        Guid aggregateId)
    {
        var streamName = $"Claim-{aggregateId}";

        var result = _client.ReadStreamAsync(
            Direction.Forwards,
            streamName,
            StreamPosition.Start
        );

        var events = new List<IDomainEvent>();

        await foreach (var resolvedEvent in result)
        {
            var @event = DeserializeEvent(resolvedEvent);
            events.Add(@event);
        }

        return events;
    }

    private IDomainEvent DeserializeEvent(ResolvedEvent resolvedEvent)
    {
        var eventType = resolvedEvent.Event.EventType;
        var type = EventTypeRegistry.GetEventType(eventType, 1);
        return (IDomainEvent)JsonSerializer.Deserialize(
            resolvedEvent.Event.Data.Span,
            type);
    }
}
```

