#### Step 2: Implement Aggregate with Event Sourcing

```csharp
public class Claim
{
    // Aggregate state (private, modified only by events)
    private Guid _id;
    private string _claimNumber;
    private ClaimStatus _status;
    private Guid _memberId;
    private Guid _providerId;
    private DateTime _serviceDate;
    private decimal _billedAmount;
    private decimal _approvedAmount;
    private List<string> _validationsPassed = new();

    // Public read-only properties
    public Guid Id => _id;
    public string ClaimNumber => _claimNumber;
    public ClaimStatus Status => _status;
    public Guid MemberId => _memberId;
    public Guid ProviderId => _providerId;
    public DateTime ServiceDate => _serviceDate;
    public decimal BilledAmount => _billedAmount;
    public decimal ApprovedAmount => _approvedAmount;

    // Event sourcing infrastructure
    private readonly List<IDomainEvent> _uncommittedEvents = new();
    public IReadOnlyList<IDomainEvent> UncommittedEvents => _uncommittedEvents;
    public long Version { get; private set; }

    public void ClearUncommittedEvents() => _uncommittedEvents.Clear();

    // Command: Submit Claim
    public void Submit(
        string claimNumber,
        Guid memberId,
        string memberName,
        Guid providerId,
        string providerName,
        DateTime serviceDate,
        string serviceCode,
        decimal billedAmount,
        string userId)
    {
        // Validation
        if (string.IsNullOrWhiteSpace(claimNumber))
            throw new ArgumentException("Claim number required");
        if (billedAmount <= 0)
            throw new ArgumentException("Billed amount must be positive");

        // Create and apply event
        var @event = new ClaimSubmittedEvent
        {
            AggregateId = Guid.NewGuid(),
            UserId = userId,
            CorrelationId = Guid.NewGuid().ToString(),
            ClaimNumber = claimNumber,
            MemberId = memberId,
            MemberName = memberName,
            ProviderId = providerId,
            ProviderName = providerName,
            ServiceDate = serviceDate,
            ServiceCode = serviceCode,
            BilledAmount = billedAmount,
            SubmittedAt = DateTime.UtcNow
        };

        ApplyChange(@event);
    }

    // Command: Validate Claim
    public void Validate(List<string> validations, string userId)
    {
        if (_status != ClaimStatus.Submitted)
            throw new InvalidOperationException(
                $"Cannot validate claim in status {_status}");

        var @event = new ClaimValidatedEvent
        {
            AggregateId = _id,
            UserId = userId,
            CorrelationId = Guid.NewGuid().ToString(),
            ValidationsPassed = validations,
            ValidatedAt = DateTime.UtcNow
        };

        ApplyChange(@event);
    }

    // Command: Adjudicate Claim
    public void Adjudicate(
        bool isApproved,
        decimal approvedAmount,
        string adjustmentReason,
        List<string> rulesEvaluated,
        string denialReason,
        string userId)
    {
        if (_status != ClaimStatus.Validated)
            throw new InvalidOperationException(
                $"Cannot adjudicate claim in status {_status}");

        if (!isApproved && string.IsNullOrWhiteSpace(denialReason))
            throw new ArgumentException("Denial reason required for denied claims");

        var @event = new ClaimAdjudicatedEvent
        {
            AggregateId = _id,
            UserId = userId,
            CorrelationId = Guid.NewGuid().ToString(),
            ClaimNumber = _claimNumber,
            AdjudicationResult = isApproved ? "Approved" : "Denied",
            BilledAmount = _billedAmount,
            ApprovedAmount = approvedAmount,
            AdjustmentReason = adjustmentReason,
            RulesEvaluated = rulesEvaluated,
            DenialReason = denialReason,
            AdjudicatedBy = Guid.Parse(userId),
            AdjudicatedAt = DateTime.UtcNow
        };

        ApplyChange(@event);
    }

    // Event application (modifies state)
    private void ApplyChange(IDomainEvent @event)
    {
        Apply(@event);  // Update internal state
        _uncommittedEvents.Add(@event);  // Track for persistence
    }

    // Apply event to aggregate state
    private void Apply(IDomainEvent @event)
    {
        switch (@event)
        {
            case ClaimSubmittedEvent e:
                Apply(e);
                break;
            case ClaimValidatedEvent e:
                Apply(e);
                break;
            case ClaimAdjudicatedEvent e:
                Apply(e);
                break;
            default:
                throw new NotSupportedException(
                    $"Event type {@event.GetType().Name} not supported");
        }
    }

    private void Apply(ClaimSubmittedEvent @event)
    {
        _id = @event.AggregateId;
        _claimNumber = @event.ClaimNumber;
        _memberId = @event.MemberId;
        _providerId = @event.ProviderId;
        _serviceDate = @event.ServiceDate;
        _billedAmount = @event.BilledAmount;
        _status = ClaimStatus.Submitted;
    }

    private void Apply(ClaimValidatedEvent @event)
    {
        _validationsPassed = @event.ValidationsPassed;
        _status = ClaimStatus.Validated;
    }

    private void Apply(ClaimAdjudicatedEvent @event)
    {
        _approvedAmount = @event.ApprovedAmount;
        _status = @event.AdjudicationResult == "Approved"
            ? ClaimStatus.Approved
            : ClaimStatus.Denied;
    }

    // Reconstitute aggregate from event history
    public static Claim LoadFromHistory(IEnumerable<IDomainEvent> history)
    {
        var claim = new Claim();

        foreach (var @event in history)
        {
            claim.Apply(@event);
            claim.Version++;
        }

        return claim;
    }
}

public enum ClaimStatus
{
    Submitted,
    Validated,
    Approved,
    Denied,
    Paid
}
```

