#### Step 1: Create Event Handler Infrastructure

```csharp
public interface IEventHandler
{
    Task HandleAsync(IDomainEvent @event);
}

// Event dispatcher routes events to handlers
public class EventDispatcher
{
    private readonly IServiceProvider _serviceProvider;

    public async Task DispatchAsync(IDomainEvent @event)
    {
        // Get all handlers for this event type
        var handlerType = typeof(IEventHandler<>)
            .MakeGenericType(@event.GetType());

        var handlers = _serviceProvider
            .GetServices(handlerType)
            .Cast<IEventHandler>();

        // Execute handlers in parallel
        var tasks = handlers.Select(h => h.HandleAsync(@event));
        await Task.WhenAll(tasks);
    }
}
