public class ClaimQueryModelHandler :
    IEventHandler<ClaimSubmittedEvent>,
    IEventHandler<ClaimValidatedEvent>,
    IEventHandler<ClaimAdjudicatedEvent>
{
    private readonly ClaimsQueryDbContext _queryDb;

    public async Task HandleAsync(ClaimSubmittedEvent @event)
    {
        var queryModel = new ClaimQueryModel
        {
            ClaimId = @event.AggregateId,
            ClaimNumber = @event.ClaimNumber,
            Status = "Submitted",
            MemberId = @event.MemberId,
            MemberName = @event.MemberName,
            ProviderId = @event.ProviderId,
            ProviderName = @event.ProviderName,
            ServiceDate = @event.ServiceDate,
            BilledAmount = @event.BilledAmount,
            SubmittedAt = @event.SubmittedAt,
            LastModifiedAt = DateTime.UtcNow
        };

        _queryDb.Claims.Add(queryModel);
        await _queryDb.SaveChangesAsync();
    }

    public async Task HandleAsync(ClaimValidatedEvent @event)
    {
        var claim = await _queryDb.Claims
            .FirstAsync(c => c.ClaimId == @event.AggregateId);

        claim.Status = "Validated";
        claim.LastModifiedAt = DateTime.UtcNow;

        await _queryDb.SaveChangesAsync();
    }

    public async Task HandleAsync(ClaimAdjudicatedEvent @event)
    {
        var claim = await _queryDb.Claims
            .FirstAsync(c => c.ClaimId == @event.AggregateId);

        claim.Status = @event.AdjudicationResult;
        claim.ApprovedAmount = @event.ApprovedAmount;
        claim.AdjudicatedAt = @event.AdjudicatedAt;
        claim.LastModifiedAt = DateTime.UtcNow;

        await _queryDb.SaveChangesAsync();
    }
}
