[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#phase-4-idempotency-implementation]

### Phase 4: Idempotency Implementation

Event handlers must be idempotent to handle duplicate event delivery safely.

```csharp
public class IdempotentEventHandler : IEventHandler
{
    private readonly IEventStore _eventStore;
    private readonly ClaimsQueryDbContext _queryDb;

    public async Task HandleAsync(IDomainEvent @event)
    {
        // Check if event already processed
        var alreadyProcessed = await _queryDb.ProcessedEvents
            .AnyAsync(e => e.EventId == @event.EventId);

        if (alreadyProcessed)
        {
            // Event already handled, skip
            return;
        }

        using var transaction = await _queryDb.Database.BeginTransactionAsync();

        try
        {
            // Process event
            await ProcessEventAsync(@event);

            // Record event as processed
            _queryDb.ProcessedEvents.Add(new ProcessedEvent
            {
                EventId = @event.EventId,
                EventType = @event.GetType().Name,
                ProcessedAt = DateTime.UtcNow
            });

            await _queryDb.SaveChangesAsync();
            await transaction.CommitAsync();
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
    }
}

// Track processed events to prevent duplicates
public class ProcessedEvent
{
    public Guid EventId { get; set; }
    public string EventType { get; set; }
    public DateTime ProcessedAt { get; set; }
}
```

