#### Strategy 1: Dual-Write Pattern (Gradual Migration)

```csharp
public class DualWriteClaimService
{
    private readonly IEventStore _eventStore;
    private readonly ClaimsDbContext _legacyDb;

    public async Task AdjudicateClaimAsync(Guid claimId)
    {
        // 1. Write to event store (new approach)
        var events = await _eventStore.LoadEventsAsync(claimId);
        var claim = Claim.LoadFromHistory(events);
        claim.Adjudicate(/* parameters */);
        await _eventStore.AppendEventsAsync(
            claimId,
            claim.UncommittedEvents,
            claim.Version);

        // 2. Write to legacy database (for backward compatibility)
        var legacyClaim = await _legacyDb.Claims.FindAsync(claimId);
        legacyClaim.Status = claim.Status.ToString();
        legacyClaim.ApprovedAmount = claim.ApprovedAmount;
        await _legacyDb.SaveChangesAsync();

        // Over time, remove legacy database writes
    }
}
