#### Strategy 2: Event Backfilling (Historical Data)

```csharp
public class EventBackfiller
{
    public async Task BackfillClaimEventsAsync(Guid claimId)
    {
        // 1. Load current claim state from legacy database
        var legacyClaim = await _legacyDb.Claims
            .Include(c => c.AuditHistory)
            .FirstAsync(c => c.Id == claimId);

        // 2. Synthesize events from audit history
        var events = new List<IDomainEvent>();

        events.Add(new ClaimSubmittedEvent
        {
            AggregateId = legacyClaim.Id,
            ClaimNumber = legacyClaim.ClaimNumber,
            MemberId = legacyClaim.MemberId,
            ProviderId = legacyClaim.ProviderId,
            BilledAmount = legacyClaim.BilledAmount,
            SubmittedAt = legacyClaim.SubmittedAt,
            UserId = "SYSTEM",
            CorrelationId = "BACKFILL"
        });

        // Synthesize validation event from audit
        var validationAudit = legacyClaim.AuditHistory
            .FirstOrDefault(a => a.Action == "Validated");
        if (validationAudit != null)
        {
            events.Add(new ClaimValidatedEvent
            {
                AggregateId = legacyClaim.Id,
                ValidatedAt = validationAudit.Timestamp,
                UserId = validationAudit.UserId,
                CorrelationId = "BACKFILL"
            });
        }

        // Synthesize adjudication event
        if (legacyClaim.AdjudicatedAt.HasValue)
        {
            events.Add(new ClaimAdjudicatedEvent
            {
                AggregateId = legacyClaim.Id,
                ClaimNumber = legacyClaim.ClaimNumber,
                AdjudicationResult = legacyClaim.Status,
                ApprovedAmount = legacyClaim.ApprovedAmount ?? 0,
                AdjudicatedAt = legacyClaim.AdjudicatedAt.Value,
                UserId = legacyClaim.AdjudicatedBy ?? "SYSTEM",
                CorrelationId = "BACKFILL"
            });
        }

        // 3. Append backfilled events to event store
        await _eventStore.AppendEventsAsync(claimId, events, 0);
    }
}
```

