```

**Schema Registry Implementation:**

```csharp
public class EventSchemaRegistry
{
    private readonly Dictionary<string, EventSchema> _schemas = new();

    public void RegisterSchema(EventSchema schema)
    {
        var key = $"{schema.EventType}_v{schema.Version}";

        if (_schemas.ContainsKey(key))
            throw new InvalidOperationException(
                $"Schema {key} already registered");

        _schemas[key] = schema;
    }

    public EventSchema GetSchema(string eventType, int version)
    {
        var key = $"{eventType}_v{version}";

        if (!_schemas.TryGetValue(key, out var schema))
            throw new KeyNotFoundException(
                $"Schema {key} not found in registry");

        return schema;
    }

    public void ValidateEvent(IDomainEvent @event)
    {
        var schema = GetSchema(@event.GetType().Name, @event.Version);

        // Validate event against JSON schema
        var validator = new JsonSchemaValidator();
        var eventJson = JsonSerializer.Serialize(@event);
        var validationResult = validator.Validate(eventJson, schema.Schema);

        if (!validationResult.IsValid)
        {
            throw new EventValidationException(
                $"Event {@event.GetType().Name} failed validation: " +
                string.Join(", ", validationResult.Errors));
        }
    }
}
```

