[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#legal-hold-capability]

#### Legal Hold Capability

Support legal holds to prevent event deletion during litigation:

```csharp
public class LegalHoldService
{
    private readonly IEventStore _eventStore;

    public async Task ApplyLegalHoldAsync(
        string caseNumber,
        Guid[] claimIds,
        DateTime holdExpirationDate)
    {
        // Mark events for specified claims as under legal hold
        foreach (var claimId in claimIds)
        {
            var events = await _eventStore.LoadEventsAsync(claimId);

            foreach (var @event in events)
            {
                await _eventStore.AddLegalHoldAsync(
                    eventId: @event.EventId,
                    caseNumber: caseNumber,
                    expirationDate: holdExpirationDate
                );
            }
        }
    }

    public async Task<bool> CanDeleteEventAsync(Guid eventId)
    {
        // Check if event is under active legal hold
        var legalHolds = await _eventStore.GetLegalHoldsAsync(eventId);

        return !legalHolds.Any(h => h.ExpirationDate > DateTime.UtcNow);
    }
}
```

