page_texts.65:
[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#field-level-encryption]

#### Field-Level Encryption

Encrypt PHI fields before storing in event store:

```csharp
public class EncryptedEventStore : IEventStore
{
    private readonly IEventStore _innerStore;
    private readonly IEncryptionService _encryption;

    public async Task AppendEventsAsync(
        Guid aggregateId,
        IEnumerable<IDomainEvent> events,
        long expectedVersion)
    {
        // Encrypt PHI fields before persistence
        var encryptedEvents = events.Select(e => EncryptPHI(e));

        await _innerStore.AppendEventsAsync(
            aggregateId,
            encryptedEvents,
            expectedVersion);
    }

    public async Task<IEnumerable<IDomainEvent>> LoadEventsAsync(Guid aggregateId)
    {
        var encryptedEvents = await _innerStore.LoadEventsAsync(aggregateId);

        // Decrypt PHI fields after retrieval
        return encryptedEvents.Select(e => DecryptPHI(e));
    }

    private IDomainEvent EncryptPHI(IDomainEvent @event)
    {
        var eventType = @event.GetType();
        var properties = eventType.GetProperties()
            .Where(p => p.GetCustomAttribute<PHIAttribute>() != null);

        var eventCopy = @event.Clone();

        foreach (var property in properties)
        {
            var value = property.GetValue(eventCopy);
            if (value != null)
            {
                var encrypted = _encryption.Encrypt(value.ToString());
                property.SetValue(eventCopy, encrypted);
            }
        }

        return eventCopy;
    }

    private IDomainEvent DecryptPHI(IDomainEvent @event)
    {
        var eventType = @event.GetType();
        var properties = eventType.GetProperties()
            .Where(p => p.GetCustomAttribute<PHIAttribute>() != null);

        var eventCopy = @event.Clone();

        foreach (var property in properties)
        {
            var encryptedValue = property.GetValue(eventCopy) as string;
            if (!string.IsNullOrEmpty(encryptedValue))
            {
                var decrypted = _encryption.Decrypt(encryptedValue);
                property.SetValue(eventCopy, decrypted);
            }
        }

        return eventCopy;
    }
}
```

page_texts.66:
[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#access-control-and-audit-logging]

#### Access Control and Audit Logging

Enforce role-based access control for event access:

```csharp
public class SecuredEventStore : IEventStore
{
    private readonly IEventStore _innerStore;
    private readonly IAuthorizationService _authz;
    private readonly IAuditLogger _auditLogger;

    public async Task<IEnumerable<IDomainEvent>> LoadEventsAsync(Guid aggregateId)
    {
        // Check user permission to access aggregate
        var currentUser = _authz.GetCurrentUser();

        if (!await _authz.CanAccessAggregateAsync(currentUser, aggregateId))
        {
            // Log unauthorized access attempt
            await _auditLogger.LogUnauthorizedAccessAsync(
                userId: currentUser.Id,
                aggregateId: aggregateId,
                action: "LoadEvents",
                ipAddress: _authz.GetClientIpAddress()
            );

            throw new UnauthorizedAccessException(
                $"User {currentUser.Id} not authorized to access aggregate {aggregateId}");
        }

        // Load events
        var events = await _innerStore.LoadEventsAsync(aggregateId);

        // Log successful PHI access (HIPAA requirement)
        await _auditLogger.LogPHIAccessAsync(
            userId: currentUser.Id,
            aggregateId: aggregateId,
            action: "LoadEvents",
            eventCount: events.Count(),
            timestamp: DateTime.UtcNow,
            ipAddress: _authz.GetClientIpAddress(),
            userAgent: _authz.GetUserAgent()
        );

        return events;
    }
}
```

