[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#right-to-be-forgotten-gdpr]

#### Right to be Forgotten (GDPR)

Handle data deletion requests while maintaining event immutability:

```csharp
public class GDPRComplianceService
{
    private readonly IEventStore _eventStore;

    public async Task HandleRightToErasureAsync(Guid memberId)
    {
        // GDPR Right to Erasure: Cannot delete events (immutable)
        // Solution: Publish compensating event with redacted data

        // 1. Find all events containing member data
        var memberEvents = await _eventStore.QueryEventsAsync(
            filter: e => e.MemberId == memberId
        );

        // 2. Publish redaction events
        foreach (var @event in memberEvents)
        {
            var redactionEvent = new MemberDataRedactedEvent
            {
                AggregateId = @event.AggregateId,
                OriginalEventId = @event.EventId,
                RedactionReason = "GDPR Right to Erasure request",
                RedactedFields = new[] { "MemberName", "DateOfBirth", "Address" },
                RequestedBy = memberId,
                RequestedAt = DateTime.UtcNow,
                UserId = "SYSTEM",
                CorrelationId = Guid.NewGuid().ToString()
            };

            await _eventStore.AppendEventsAsync(
                @event.AggregateId,
                new[] { redactionEvent },
                expectedVersion: @event.SequenceNumber
            );
        }

        // 3. Update projections to show redacted data
        // Event handlers will see redaction event and update query models
    }
}

public record MemberDataRedactedEvent : IDomainEvent
{
    public Guid EventId { get; init; }
    public string AggregateType => "Member";
    public Guid AggregateId { get; init; }
    public int Version { get; init; } = 1;
    public string UserId { get; init; }
    public DateTime Timestamp { get; init; }
    public string CorrelationId { get; init; }

    public Guid OriginalEventId { get; init; }
    public string RedactionReason { get; init; }
    public string[] RedactedFields { get; init; }
    public Guid RequestedBy { get; init; }
    public DateTime RequestedAt { get; init; }
}
```

