#### Event Store Audit Reports

Generate compliance reports from event store:

```csharp
public class ComplianceReportingService
{
    private readonly IEventStore _eventStore;

    // HIPAA Access Report: All PHI access in date range
    public async Task<HIPAAAccessReport> GenerateHIPAAAccessReportAsync(
        DateTime startDate,
        DateTime endDate)
    {
        var accessEvents = await _eventStore.QueryEventsAsync<PHIAccessedEvent>(
            filter: e => e.Timestamp >= startDate && e.Timestamp <= endDate
        );

        return new HIPAAAccessReport
        {
            ReportPeriod = $"{startDate:yyyy-MM-dd} to {endDate:yyyy-MM-dd}",
            TotalAccessEvents = accessEvents.Count(),
            UniqueUsers = accessEvents.Select(e => e.UserId).Distinct().Count(),
            UniqueMembersAccessed = accessEvents.Select(e => e.MemberId).Distinct().Count(),
            AccessByUser = accessEvents.GroupBy(e => e.UserId)
                .Select(g => new UserAccessSummary
                {
                    UserId = g.Key,
                    AccessCount = g.Count(),
                    FirstAccess = g.Min(e => e.Timestamp),
                    LastAccess = g.Max(e => e.Timestamp)
                })
                .ToList()
        };
    }

    // Claim Adjudication Audit: Complete audit trail for claim
    public async Task<ClaimAuditTrail> GenerateClaimAuditTrailAsync(Guid claimId)
    {
        var events = await _eventStore.LoadEventsAsync(claimId);

        return new ClaimAuditTrail
        {
            ClaimId = claimId,
            TotalEvents = events.Count(),
            FirstEvent = events.First().Timestamp,
            LastEvent = events.Last().Timestamp,
            StateTransitions = events.Select(e => new StateTransition
            {
                EventType = e.GetType().Name,
                Timestamp = e.Timestamp,
                UserId = e.UserId,
                Details = SerializeEventDetails(e)
            }).ToList()
        };
    }
}
