#### NCQA Audit Query

```csharp
// NCQA Audit Question: "Show provider's credential status on October 1, 2023"
public async Task<ProviderCredentialSnapshot> GetCredentialStatusAtDateAsync(
    Guid providerId,
    DateTime auditDate)
{
    // Replay events up to audit date
    var events = await _eventStore.LoadEventsUntilAsync(providerId, auditDate);
    var provider = Provider.LoadFromHistory(events);

    return new ProviderCredentialSnapshot
    {
        ProviderId = providerId,
        SnapshotDate = auditDate,
        Credentials = provider.Credentials.Select(c => new CredentialStatus
        {
            CredentialType = c.Type,
            CredentialNumber = c.Number,
            Status = c.Status,  // "Active" (would show "Active" on Oct 1, 2023)
            ExpirationDate = c.ExpirationDate,  // 2023-12-31
            DaysUntilExpiration = (c.ExpirationDate - auditDate).Days  // 91 days
        }).ToList()
    };
}

// Result:
// Provider Credential Status as of 2023-10-01:
//   Medical License MD-12345:
//     Status: Active (but expiring soon)
//     Expiration: 2023-12-31
//     Days Until Expiration: 91
//   DEA Registration: Active
//   Malpractice Insurance: Active
```

