#### Traditional Approach (Problems)

```csharp
// Traditional approach - overwrites eligibility
public class TraditionalEligibilityService
{
    public async Task UpdateEligibilityAsync(
        Guid memberId,
        DateTime effectiveDate,
        DateTime terminationDate)
    {
        var eligibility = await _db.Eligibility.FindAsync(memberId);

        // Update overwrites previous values - ORIGINAL VALUES LOST
        eligibility.EffectiveDate = effectiveDate;
        eligibility.TerminationDate = terminationDate;

        await _db.SaveChangesAsync();

        // PROBLEM: Cannot reconstruct why claim was originally denied
        // Was denial ONLY due to eligibility, or were there other issues?
        // If we reprocess claim with corrected eligibility, will we get same result?

        // Find claims to reprocess
        var claims = await _db.Claims
            .Where(c => c.MemberId == memberId
                     && c.ServiceDate >= effectiveDate
                     && c.ServiceDate <= terminationDate)
            .ToListAsync();

        // Reprocess claims - but audit trail confusing
        foreach (var claim in claims)
        {
            await ReprocessClaimAsync(claim.ClaimId);
            // Audit shows: Claim Denied → Claim Approved
            // But WHY? Doesn't explain retroactive eligibility correction
        }
    }
}
