[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#reprocessing-with-complete-context]

#### Reprocessing with Complete Context

```csharp
public class RetroactiveClaimReprocessor
{
    private readonly IEventStore _eventStore;

    public async Task ReprocessClaimWithRetroactiveEligibilityAsync(
        Guid claimId,
        Guid memberId,
        DateTime serviceDate,
        EligibilitySpanCorrectedEvent correctionEvent)
    {
        // 1. Load claim event history to understand ORIGINAL denial reason
        var claimEvents = await _eventStore.LoadEventsAsync(claimId);
        var claim = Claim.LoadFromHistory(claimEvents);

        // 2. Determine if claim was denied ONLY due to eligibility
        var denialEvent = claimEvents.OfType<ClaimDeniedEvent>().FirstOrDefault();

        if (denialEvent != null &&
            denialEvent.DenialReason.Contains("not eligible"))
        {
            // 3. Reprocess claim with corrected eligibility
            var eligibilityEvents = await _eventStore.LoadEventsAsync(memberId);
            var member = Member.LoadFromHistory(eligibilityEvents);

            // 4. Check if member now eligible on service date
            var wasEligible = member.IsEligibleOnDate(serviceDate);

            if (wasEligible)
            {
                // 5. Create retroactive correction event with full context
                var correctionClaimEvent = new ClaimRetroactivelyCorrectedEvent
                {
                    ClaimId = claimId,
                    ClaimNumber = claim.ClaimNumber,
                    OriginalDenialReason = denialEvent.DenialReason,
                    OriginalDeniedAt = denialEvent.DeniedAt,
                    CorrectionReason = $"Retroactive eligibility correction: {correctionEvent.CorrectionReason}",
                    EligibilityCorrectionEventId = correctionEvent.EventId,
                    NewStatus = "Approved",
                    ApprovedAmount = claim.CalculateApprovedAmount(),
                    CorrectedAt = DateTime.UtcNow,
                    CorrectedBy = "SYSTEM"
                };

                // 6. Append event to claim aggregate
                await _eventStore.AppendEventsAsync(
                    claimId,
                    new[] { correctionClaimEvent },
                    expectedVersion: claim.Version
                );

                // Audit trail now shows:
                // - Original claim denial (with reasoning)
                // - Eligibility correction event (with state agency reasoning)
                // - Claim retroactive correction (linking back to eligibility change)
                // COMPLETE CONTEXT for audit purposes
            }
        }
    }
}
```

