[patterns/application/api-microservices/PTN-APP-API-012-event-sourcing-pattern.md#quick-start]

### Quick Start

**1. Define Domain Events (Past Tense):**

```csharp
public record ClaimAdjudicatedEvent : IDomainEvent
{
    public Guid ClaimId { get; init; }
    public string AdjudicationResult { get; init; }  // "Approved" or "Denied"
    public decimal ApprovedAmount { get; init; }
    public string AdjustmentReason { get; init; }
    public List<string> RulesEvaluated { get; init; }
    public Guid AdjudicatedBy { get; init; }
    public DateTime AdjudicatedAt { get; init; }
}
```

**2. Create Event Store (PostgreSQL):**

```sql
CREATE TABLE events (
    event_id UUID PRIMARY KEY,
    aggregate_id UUID NOT NULL,
    event_type VARCHAR(200) NOT NULL,
    sequence_number BIGINT NOT NULL,
    event_data JSONB NOT NULL,
    metadata JSONB NOT NULL,
    created_at TIMESTAMP NOT NULL,
    UNIQUE (aggregate_id, sequence_number)
);

CREATE INDEX idx_events_aggregate ON events(aggregate_id, sequence_number);
```

**3. Implement Aggregate:**

```csharp
public class Claim
{
    private Guid _id;
    private ClaimStatus _status;
    private decimal _approvedAmount;

    public long Version { get; private set; }
    private readonly List<IDomainEvent> _uncommittedEvents = new();

    // Command: Adjudicate Claim
    public void Adjudicate(bool approved, decimal amount)
    {
        var @event = new ClaimAdjudicatedEvent
        {
            ClaimId = _id,
            AdjudicationResult = approved ? "Approved" : "Denied",
            ApprovedAmount = amount,
            AdjudicatedAt = DateTime.UtcNow
        };

        Apply(@event);  // Update state
        _uncommittedEvents.Add(@event);  // Track for persistence
    }

    // Apply event to state
    private void Apply(ClaimAdjudicatedEvent @event)
    {
        _status = @event.AdjudicationResult == "Approved"
            ? ClaimStatus.Approved
            : ClaimStatus.Denied;
        _approvedAmount = @event.ApprovedAmount;
    }

    // Reconstitute from history
    public static Claim LoadFromHistory(IEnumerable<IDomainEvent> events)
    {
        var claim = new Claim();
        foreach (var @event in events)
        {
            claim.Apply(@event);
            claim.Version++;
        }
        return claim;
    }
}
```

**4. Persist Events:**

```csharp
// Command handler
public async Task AdjudicateClaimAsync(Guid claimId)
{
    // Load from event history
    var events = await _eventStore.LoadEventsAsync(claimId);
    var claim = Claim.LoadFromHistory(events);

    // Execute command
    claim.Adjudicate(approved: true, amount: 150.00m);

    // Persist events
    await _eventStore.AppendEventsAsync(
        claimId,
        claim.UncommittedEvents,
        expectedVersion: claim.Version
    );
}
```

**5. Build Projections (CQRS):**

```csharp
// Event handler updates read model
public class ClaimQueryModelHandler : IEventHandler<ClaimAdjudicatedEvent>
{
    public async Task HandleAsync(ClaimAdjudicatedEvent @event)
    {
        var claim = await _queryDb.Claims.FindAsync(@event.ClaimId);
        claim.Status = @event.AdjudicationResult;
        claim.ApprovedAmount = @event.ApprovedAmount;
        await _queryDb.SaveChangesAsync();
    }
}
```
